-- ----------------------------
-- Table structure for t_data_scope_config
-- ----------------------------
DROP TABLE IF EXISTS `t_data_scope_config`;
CREATE TABLE `t_data_scope_config`  (
                                        `config_id` bigint NOT NULL AUTO_INCREMENT COMMENT '配置ID',
                                        `config_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '配置编码（用于代码中引用）',
                                        `config_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '配置名称',
                                        `config_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '配置描述',
                                        `business_module` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务模块名称',
                                        `default_view_type` int NULL DEFAULT NULL COMMENT '默认视图类型0: 仅本人1: 部门2: 本部门及以下3: 全部数据',
                                        `sort_order` int NULL DEFAULT 0 COMMENT '排序',
                                        `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态（0-禁用，1-启用）',
                                        `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                        `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                        `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
                                        `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
                                        PRIMARY KEY (`config_id`) USING BTREE,
                                        UNIQUE INDEX `uk_config_code`(`config_code` ASC) USING BTREE,
                                        INDEX `idx_business_module`(`business_module` ASC) USING BTREE,
                                        INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '数据权限配置表' ROW_FORMAT = DYNAMIC;

