-- ----------------------------
-- Table structure for t_permission_data_rule
-- ----------------------------
DROP TABLE IF EXISTS `t_permission_data_rule`;
CREATE TABLE `t_permission_data_rule`  (
                                           `rule_id` bigint NOT NULL AUTO_INCREMENT COMMENT '规则ID',
                                           `permission_id` bigint NOT NULL COMMENT '权限ID（菜单权限ID）',
                                           `rule_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '规则名称',
                                           `rule_column` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '规则字段（如：create_by、dept_id）',
                                           `rule_conditions` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '规则条件（=、!=、>、<、like、in等）',
                                           `rule_value` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '规则值（支持SQL变量：#{sys_user_id}、#{sys_user_name}、#{sys_depart_id}、#{sys_depart_ids}）',
                                           `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态（0-禁用，1-启用）',
                                           `sort_order` int NULL DEFAULT 0 COMMENT '排序',
                                           `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
                                           `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
                                           `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
                                           `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
                                           PRIMARY KEY (`rule_id`) USING BTREE,
                                           INDEX `idx_permission_id`(`permission_id` ASC) USING BTREE,
                                           INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '数据权限规则表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_permission_data_rule
-- ----------------------------
INSERT INTO `t_permission_data_rule` VALUES (1, 1, '只看自己创建的数据', 'create_by', '=', '#{sys_user_code}', 1, 1, '2026-02-21 10:38:00', '2026-02-21 10:38:00', NULL, NULL);
INSERT INTO `t_permission_data_rule` VALUES (2, 1, '只看本部门数据', 'dept_id', '=', '#{sys_depart_id}', 1, 2, '2026-02-21 10:38:00', '2026-02-21 10:38:00', NULL, NULL);
INSERT INTO `t_permission_data_rule` VALUES (3, 1, '看本部门及子部门数据', 'dept_id', 'IN', '#{sys_depart_ids}', 1, 3, '2026-02-21 10:38:00', '2026-02-21 10:38:00', NULL, NULL);

-- ----------------------------
-- Table structure for t_position
-- ----------------------------
DROP TABLE IF EXISTS `t_position`;
CREATE TABLE `t_position`  (
                               `position_id` bigint NOT NULL AUTO_INCREMENT COMMENT '职务ID',
                               `position_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '职务名称',
                               `position_level` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职级',
                               `sort` int NULL DEFAULT 0 COMMENT '排序',
                               `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
                               `deleted_flag` tinyint(1) NULL DEFAULT 0,
                               `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
                               `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                               PRIMARY KEY (`position_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '职务表' ROW_FORMAT = DYNAMIC;

